// Keep action visibility in sync with scrolling: once the new frame lays
// out visible rows, bump the controller's epoch so the crumb UI can
// re-evaluate whether the playing track is currently visible.
useEffect(() {
  if (browserController == null) return null;

  void onScroll() {
    if (visibilityBumpScheduled.value) return;
    visibilityBumpScheduled.value = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      visibilityBumpScheduled.value = false;
      browserController!.bumpVisibilityEpoch();
    });
  }

  scroll.addListener(onScroll);
  return () => scroll.removeListener(onScroll);
}, [scroll, browserController]);

